export function Autocomplete({
  label = "{{label}}",
  placeholder = "{{placeholder}}",
  query = "{{query}}",
  open = {{open}},
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  return (
    <div style={{ display: "block", fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 300 }}>
      <label htmlFor="ac-input-r" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</label>
      <div style={{ position: "relative" }} role="combobox" aria-haspopup="listbox" aria-owns="ac-listbox-r" aria-expanded={open}>
        <input
          id="ac-input-r"
          type="text"
          role="textbox"
          aria-autocomplete="list"
          aria-controls="ac-listbox-r"
          aria-activedescendant="ac-opt-r-1"
          placeholder={placeholder}
          defaultValue={query}
          autoComplete="off"
          style={{ width: "100%", boxSizing: "border-box", padding: "10px 12px", font: "inherit", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143040", borderRadius: radius }}
        />
        <ul id="ac-listbox-r" role="listbox" aria-label={label + " suggestions"} style={{
          display: open ? "block" : "none", listStyle: "none", margin: "4px 0 0", padding: 4,
          border: "1.5px solid #24143020", background: "#FAF7F2", boxShadow: "0 8px 20px #24143022", maxHeight: 180, overflow: "auto",
        }}>
          <li id="ac-opt-r-1" role="option" aria-selected="true" style={{ padding: "8px 10px", borderRadius: 6, cursor: "pointer", background: accent }}>{query} Francisco</li>
          <li id="ac-opt-r-2" role="option" aria-selected="false" style={{ padding: "8px 10px", borderRadius: 6, cursor: "pointer" }}>{query} Antonio</li>
          <li id="ac-opt-r-3" role="option" aria-selected="false" style={{ padding: "8px 10px", borderRadius: 6, cursor: "pointer" }}>{query} Diego</li>
        </ul>
      </div>
    </div>
  );
}
